const rows = $input.first().json.data;
const wpUrl = rows.find(r => r[0] === 'wordpress_url')?.[1] || '';
const wpUser = rows.find(r => r[0] === 'wordpress_username')?.[1] || '';
const wpPass = rows.find(r => r[0] === 'wordpress_app_password')?.[1] || '';
if (!wpUrl || !wpUser || !wpPass) throw new Error('WordPress credentials not configured in CONFIG tab');
return [{
  json: {
    wp_url: wpUrl,
    wp_user: wpUser,
    wp_pass: wpPass
  }
}];

const input = $input.first().json;
const wp = $input.first().json;

// Parse title_meta JSON if provided as string
let titleMeta = input.title_meta || {};
if (typeof titleMeta === 'string') {
  try { titleMeta = JSON.parse(titleMeta); } catch (e) {}
}

// Convert markdown article to HTML if needed (simple conversion)
let content = input.article || '';

return [{
  json: {
    wp_url: wp.wp_url,
    wp_user: wp.wp_user,
    wp_pass: wp.wp_pass,
    title: titleMeta.title || input.keyword || 'Article',
    content: content,
    excerpt: titleMeta.meta_description || '',
    slug: titleMeta.slug || input.keyword?.toLowerCase().replace(/\s+/g, '-') || 'article',
    status: 'publish',
    featured_media: input.featured_image_id || 0,
    categories: input.category_ids || [1],
    tags: input.tag_ids || []
  }
}];

const resp = $input.first().json;
const postUrl = resp.link || '';
const postId = resp.id || 0;
if (!postId) throw new Error('WordPress publish failed: ' + JSON.stringify(resp));
return [{
  json: {
    post_url: postUrl,
    post_id: postId,
    status: 'published',
    step: '5A'
  }
}];

return [{
  json: {
    post_url: $input.first().json.post_url,
    post_id: $input.first().json.post_id,
    status: 'done',
    step: '5A'
  }
}];
